-- Expanded from examples/revenue.sql. Runs in any DuckDB 2.0+ client; no extension needed.
-- Generated by notebook_sql(); edit the notebook, not this file.

-- Variables read by cells but set only interactively start as NULL.
SET VARIABLE "picked_months" = NULL;

-- sql cell orders (line 16)
-- Effect cell: creates a table, so it only runs when asked.
CREATE OR REPLACE TABLE orders AS
SELECT
    i AS order_id,
    TIMESTAMP '2026-01-01' + INTERVAL (i * 37 % 525600) MINUTE AS ts,
    ['EU', 'US', 'APAC'][1 + i % 3] AS region,
    ['Hardware', 'Software', 'Services'][1 + (i // 3) % 3] AS category,
    round(20 + (i * 7919 % 500) * (1 + (i % 3) * 0.25), 2) AS amount
FROM range(50000) t(i);

-- sql cell regions (line 27)
CREATE OR REPLACE TEMP VIEW "regions" AS
SELECT DISTINCT region AS name FROM orders ORDER BY name;

-- input cell region (line 30)
SET VARIABLE region = 'EU';

-- input cell min_amount (line 33)
SET VARIABLE min_amount = 0;

-- sql cell filtered (line 36)
CREATE OR REPLACE TEMP VIEW "filtered" AS
SELECT *
FROM orders
WHERE region = $region
  AND amount >= $min_amount;

-- sql cell monthly (line 42)
CREATE OR REPLACE TEMP VIEW "monthly" AS
SELECT
    date_trunc('month', ts) AS month,
    category,
    sum(amount) AS revenue,
    count(*) AS orders
FROM filtered
GROUP BY ALL
ORDER BY month, category;

-- sql cell top_orders (line 87)
-- `picked_months` is set by brushing the trend chart; NULL means no brush.
CREATE OR REPLACE TEMP VIEW "top_orders" AS
SELECT order_id, ts, category, amount
FROM filtered
WHERE $picked_months IS NULL
   OR ts BETWEEN $picked_months.lo AND $picked_months.hi
ORDER BY amount DESC
LIMIT 20;
